// Merge extra question bank (~300 more questions)
import { quizQuestionsExtra } from "./quizQuestionsExtra";
import { quizQuestionsMega } from "./quizQuestionsMega";
(quizQuestions as QuizQuestion[]).push(...quizQuestionsExtra, ...quizQuestionsMega);

// --- Anti-repeat tracking: avoid showing recently-seen questions ---
const RECENT_KEY = "cw_quiz_recent_ids";
const RECENT_MAX = 250; // remember last 250 — bank is 670+, so fresh-feel for weeks


function getRecentIds(): string[] {
  try {
    const raw = localStorage.getItem(RECENT_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch { return []; }
}

export function markQuestionsSeen(ids: string[]) {
  try {
    const recent = getRecentIds();
    const merged = [...ids, ...recent].slice(0, RECENT_MAX);
    localStorage.setItem(RECENT_KEY, JSON.stringify(Array.from(new Set(merged))));
  } catch { /* ignore */ }
}

/** Get questions filtered by difficulty */
export function getQuestionsByDifficulty(difficulty: 1 | 2 | 3): QuizQuestion[] {
  return quizQuestions.filter((q) => q.difficulty === difficulty);
}

/** Get a random set of N questions, optionally filtered */
/** Get a random set of N questions, optionally filtered. Excludes recently-seen when possible. */
export function getRandomQuestions(count: number, difficulty?: 1 | 2 | 3): QuizQuestion[] {
  const fullPool = difficulty ? getQuestionsByDifficulty(difficulty) : [...quizQuestions];
  const recent = new Set(getRecentIds());
  // Prefer unseen; fall back to full pool if not enough
  const fresh = fullPool.filter((q) => !recent.has(q.id));
  const pool = fresh.length >= count ? fresh : fullPool;
  const shuffled = [...pool].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, Math.min(count, shuffled.length));
}

/** Get daily questions - deterministic based on date */
export function getDailyQuestions(): QuizQuestion[] {
  const today = new Date().toISOString().split("T")[0];
  let seed = 0;
  for (let i = 0; i < today.length; i++) {
    seed = ((seed << 5) - seed + today.charCodeAt(i)) | 0;
  }

  const seededRandom = (s: number) => {
    const x = Math.sin(s) * 10000;
    return x - Math.floor(x);
  };

  const pool = [...quizQuestions];
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(seededRandom(seed + i) * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }

  // Pick 10: 4 easy, 4 medium, 2 hard — daily challenge feels meaty + addictive
  const easy = pool.filter((q) => q.difficulty === 1).slice(0, 4);
  const medium = pool.filter((q) => q.difficulty === 2).slice(0, 4);
  const hard = pool.filter((q) => q.difficulty === 3).slice(0, 2);
  return [...easy, ...medium, ...hard];
}
